import{_ as t,o,c as s,j as e,a as r}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/10-进化的纽带：基因决定依恋风格.md","filePath":"books/attached/10-进化的纽带：基因决定依恋风格.md","lastUpdated":1794298621000}'),n={name:"books/attached/10-进化的纽带：基因决定依恋风格.md"};function _(l,a,d,c,p,i){return o(),s("div",null,[...a[0]||(a[0]=[e("h3",{id:"进化的纽带-基因决定依恋风格",tabindex:"-1"},[r("进化的纽带：基因决定依恋风格 "),e("a",{class:"header-anchor",href:"#进化的纽带-基因决定依恋风格","aria-label":'Permalink to "进化的纽带：基因决定依恋风格"'},"​")],-1),e("p",null,"依恋理论建立在这样的一种主张上：对于亲密关系的这种需要，是根植于我们的基因中的。正是约翰·鲍尔比（John Bowlby）[2]的才华，让他认识到，进化使得我们会在我们的生命中选择出少数几个个体，视为珍爱。我们生而必须依赖一位重要的人。这种需要从生命伊始，一直延续到生命终止。鲍尔比认为，在整个进化史中，基因选择令人们变得更有依恋性，其实是因为如此一来更有生存优势。在史前时代，单单依靠个体自身的人，很难在猎食者面前保护自己周全。因此，这些依靠着亲密伴侣而活下来的人，往往会将自己对亲密关系的偏好传递给下一代。事实上，正因为对亲密角色的需要是非常重要的，因此我们的大脑才进化出一种生物性机能，专门负责建构与规制我们与依恋对象（包括父母、子女以及爱侣）的联结。这种机能就是依恋体系（attachment system），这是一种确保我们必须通过接近所爱之人，才能保证安全的情感与行为的集合。这种机制解释了为什么孩子一旦离开母亲，就会陷入疯狂，不断地张望，或是止不住地哭喊，直到跟母亲重新接触上。这些反应就是防御行为（protest behavior），我们直到成年后还依然会显露出来。在史前时代，与同伴的亲密关系事关生死，因此我们的依恋体系将这种亲密关系视为不可或缺的。",-1),e("p",null,"让我们来想象一下，若是你听到一条新闻，就在你伴侣从纽约飞往伦敦的那天晚上，大西洋上空有一架飞机坠毁了。那时候你所感到的惴惴不安和歇斯底里，其实就是你的依恋体系正在运作。而你迫不及待地打电话给机场，则正是你的防御行为。",-1),e("p",null,"进化有一个非常重要的方面，那就是多元化的发展。人类本来就是异质性很强的物种，无论外形、态度还是行为，都天差地别。这就解释了我们为什么有着如此顽强的生命力，能够存活在地球的几乎每一个角落。若是我们都如出一辙，那么单单是某一种自然灾害，就可能把人类从地球上灭绝。我们的多样性保证了人类的每一个分支，相对于其他物种来说，人类有着独一无二的存活能力。而依恋风格与人类的其他特征别无二致。虽然我们都有着基本的亲密需要，但是所用的方式千差万别。在非常危急的环境中，将时间与精力投入在一个人身上，就对自己没什么好处，毕竟他或许并不能长久地伴你左右；或许这时候人们就会想办法不那么依恋他人，随时准备离开（这也就是后来的回避型依恋风格）。而在艰难条件下的另一种截然相反的生存选择，就是在依恋对象面前，表现得过于警觉（因此，焦虑型依恋风格就应运而生）。而在一个更为安全的环境下，人们普遍愿意与他人结成亲密关系，这样对双方及他们的后代来说，都能谋得更多的裨益（自此，就产生了安全型依恋风格）。",-1),e("p",null,"诚然，在现代社会，我们无须像祖先那样，逃避捕食者们的追逐。但是从进化的角度来说，我们与老祖宗们几乎没什么差别。我们大脑的情绪系统，从远古的智人那里延续下来，我们的情感中，暗含着它们的生活方式以及应对危险的方式。在现如今的亲密关系中，我们的感受与行为与远古的祖先，几乎别无二致。",-1)])])}const f=t(n,[["render",_]]);export{m as __pageData,f as default};
